import heapq

def match(orders):
    trades = []

    # order_book[id] = dict with side, price, qty (remaining), arrival, active
    book = {}

    # heaps store tuples for priority
    # buy_heap: (-price, arrival, id)
    # sell_heap: (price, arrival, id)
    buy_heap = []
    sell_heap = []

    arrival_counter = 0

    def add_to_book(order_id, side, price, qty, arrival):
        book[order_id] = {
            'side': side,
            'price': price,
            'qty': qty,
            'arrival': arrival,
            'active': True
        }
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, arrival, order_id))
        else:
            heapq.heappush(sell_heap, (price, arrival, order_id))

    def clean_top(heap):
        # remove inactive orders from top of heap
        while heap:
            top = heap[0]
            oid = top[2]
            if oid not in book or not book[oid]['active'] or book[oid]['qty'] <= 0:
                heapq.heappop(heap)
            else:
                break

    for order in orders:
        op = order[0]

        if op == 'cancel':
            order_id = order[1]
            if order_id in book and book[order_id]['active'] and book[order_id]['qty'] > 0:
                book[order_id]['active'] = False
            continue

        # parse order details
        if op == 'limit':
            _, order_id, side, price, qty = order
        elif op == 'ioc':
            _, order_id, side, price, qty = order
        elif op == 'market':
            _, order_id, side, qty = order
            price = None
        else:
            continue

        arrival = arrival_counter
        arrival_counter += 1

        remaining_qty = qty

        if side == 'buy':
            opposite_heap = sell_heap
        else:
            opposite_heap = buy_heap

        while remaining_qty > 0:
            clean_top(opposite_heap)
            if not opposite_heap:
                break

            if side == 'buy':
                resting_price, resting_arrival, resting_id = opposite_heap[0]
            else:
                resting_price, resting_arrival, resting_id = opposite_heap[0]

            # check price condition
            if op == 'market':
                can_match = True
            else:
                if side == 'buy':
                    can_match = price >= resting_price
                else:
                    can_match = price <= resting_price

            if not can_match:
                break

            # pop this resting order
            heapq.heappop(opposite_heap)

            resting_order = book[resting_id]
            resting_qty = resting_order['qty']

            trade_qty = min(remaining_qty, resting_qty)

            if side == 'buy':
                buy_id = order_id
                sell_id = resting_id
            else:
                buy_id = resting_id
                sell_id = order_id

            trades.append([buy_id, sell_id, resting_price, trade_qty])

            remaining_qty -= trade_qty
            resting_order['qty'] -= trade_qty

            if resting_order['qty'] <= 0:
                resting_order['active'] = False
            else:
                # push back since still has remaining qty
                if resting_order['side'] == 'buy':
                    heapq.heappush(buy_heap, (-resting_order['price'], resting_order['arrival'], resting_id))
                else:
                    heapq.heappush(sell_heap, (resting_order['price'], resting_order['arrival'], resting_id))

        # if limit order and remaining qty > 0, add to book
        if op == 'limit' and remaining_qty > 0:
            add_to_book(order_id, side, price, remaining_qty, arrival)
        # ioc and market discard remainder

    return trades

